# Public API (cm:*)
  @api cm:setContext(newTake)  @ 420-425
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 418
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 419
  @api cm:clearTake()  @ 427-432
  @api cm:boundTake()  @ 435
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 434
  @api cm:boundTrack()  @ 438
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 437
  @api cm:setTrack(newTrack)  @ 440-445
  @api cm:pollUndo()  @ 448
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 447
  @api cm:isDeclared(key)  @ 485
      @contract  non-raising existence test against the schema; true iff key is declared  @ 484
  @api cm:get(key, opts)  @ 489-493
      @contract  deep-copy of resolved value (most-specific tier, else default); raises on unknown key  @ 487
      @contract  opts.mergeTiers=true → per-subkey union across defaults+tiers; table-valued keys only  @ 488
  @api cm:getAt(level, key)  @ 496-505
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 495
  @api cm:valueFor(handle, scope, key)  @ 508-515
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 507
  @api cm:defaultFor(key)  @ 518-521
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 517
  -- Writing
  @api cm:set(level, key, value)  @ 526-536
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 525
  @api cm:remove(level, key)  @ 539-550
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 538
  @api cm:assign(level, updates)  @ 553-567
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 552

